"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { formatTime } from "../lib/date";
import { type ScheduleEvent, type ScheduleResource, groupByStart } from "../lib/schedule";

export interface TimeSlotListProps extends React.HTMLAttributes<HTMLDivElement> {
  events: ScheduleEvent[];
  /** Resources voor kleur, avatar en het label rechts op een kaart. */
  resources?: ScheduleResource[];
  /** Toont de naam van de resource als tag op elke kaart. */
  showResource?: boolean;
  /** Aantal kolommen waarin de kaarten van één tijdslot worden gelegd. */
  minCardWidth?: number;
  emptyLabel?: React.ReactNode;
  onEventClick?: (event: ScheduleEvent) => void;
  /** Eigen inhoud voor een kaart. */
  renderEvent?: (event: ScheduleEvent, resource?: ScheduleResource) => React.ReactNode;
  /** Extra tekst of knoppen rechtsonder op een kaart. */
  renderEventMeta?: (event: ScheduleEvent) => React.ReactNode;
}

/**
 * TimeSlotList — de dag als verticale tijdlijn: per tijdstip één regel, met
 * daarnaast een kaartje voor elke afspraak op dat moment. Leest als een
 * dagoverzicht en werkt goed op smalle schermen.
 */
export const TimeSlotList = React.forwardRef<HTMLDivElement, TimeSlotListProps>(
  function TimeSlotList(
    {
      events,
      resources,
      showResource = true,
      minCardWidth = 230,
      emptyLabel = "Niets gepland",
      onEventClick,
      renderEvent,
      renderEventMeta,
      className,
      ...rest
    },
    ref
  ) {
    const byKey = React.useMemo(() => {
      const map = new Map<string, ScheduleResource>();
      for (const resource of resources ?? []) map.set(resource.key, resource);
      return map;
    }, [resources]);

    const slots = React.useMemo(() => groupByStart(events), [events]);

    if (slots.length === 0) {
      return (
        <div ref={ref} className={cn("pxui-slots", className)} {...rest}>
          <div className="pxui-slots-empty">{emptyLabel}</div>
        </div>
      );
    }

    return (
      <div ref={ref} className={cn("pxui-slots", className)} {...rest}>
        {slots.map((slot) => (
          <div className="pxui-slot" key={slot.start}>
            <div className="pxui-slot-time">
              <span className="pxui-slot-time-label">{formatTime(slot.start)}</span>
            </div>

            <div
              className="pxui-slot-cards"
              style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${minCardWidth}px, 1fr))` }}
            >
              {slot.events.map((event) => {
                const resource = byKey.get(event.resource);
                const color = event.color ?? resource?.color;
                const tone = event.tone ?? "accent";

                return (
                  <div
                    key={event.id}
                    role={onEventClick && !event.blocked ? "button" : undefined}
                    tabIndex={onEventClick && !event.blocked ? 0 : undefined}
                    className={cn("pxui-slot-card", event.blocked && "pxui-slot-card-blocked")}
                    style={color ? ({ ["--pxui-event-color" as string]: color } as React.CSSProperties) : undefined}
                    onClick={() => !event.blocked && onEventClick?.(event)}
                    onKeyDown={(keyEvent) => {
                      if (keyEvent.key === "Enter" || keyEvent.key === " ") {
                        keyEvent.preventDefault();
                        if (!event.blocked) onEventClick?.(event);
                      }
                    }}
                  >
                    {renderEvent ? (
                      renderEvent(event, resource)
                    ) : (
                      <>
                        {resource?.media && <span className="pxui-slot-media">{resource.media}</span>}
                        <span className="pxui-slot-body">
                          <span className="pxui-slot-title">{event.title}</span>
                          <span className="pxui-slot-meta">
                            {!event.blocked && (
                              <span className={cn("pxui-slot-dot", `pxui-tone-${tone}`)} aria-hidden="true" />
                            )}
                            {event.subtitle ?? `${event.end - event.start} min`}
                            {renderEventMeta?.(event)}
                          </span>
                        </span>
                        {showResource && resource && (
                          <span
                            className="pxui-slot-tag"
                            style={
                              resource.color
                                ? {
                                    background: `color-mix(in srgb, ${resource.color} 14%, transparent)`,
                                    color: resource.color,
                                  }
                                : undefined
                            }
                          >
                            {resource.label}
                          </span>
                        )}
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    );
  }
);

/* ============================ TimeSlotList ============================ */
.pxui-slots { display: flex; flex-direction: column; min-width: 0; }
.pxui-slots-empty {
  padding: 40px 16px; text-align: center;
  font-size: 13px; color: var(--text-3); font-style: italic;
}

.pxui-slot { display: flex; align-items: flex-start; gap: 14px; padding: 10px 0; }
.pxui-slot + .pxui-slot { border-top: 1px dashed var(--border); }

.pxui-slot-time {
  flex: none; width: 62px; padding-top: 8px;
  display: flex; justify-content: flex-end;
}
.pxui-slot-time-label {
  font-size: 13px; font-weight: 700; color: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.pxui-slot-cards { flex: 1; min-width: 0; display: grid; gap: 8px; }

.pxui-slot-card {
  --pxui-event-color: var(--accent);
  display: flex; align-items: center; gap: 10px; min-width: 0;
  padding: 9px 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 3px solid var(--pxui-event-color);
  border-radius: var(--r-md);
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast), background var(--dur-fast);
}
.pxui-slot-card[role="button"] { cursor: pointer; }
.pxui-slot-card[role="button"]:hover { box-shadow: var(--sh-sm); border-color: var(--border-strong); }
.pxui-slot-card[role="button"]:focus-visible { outline: none; box-shadow: var(--ring); }

.pxui-slot-media { flex: none; display: flex; }
.pxui-slot-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.pxui-slot-title {
  font-size: 13.5px; font-weight: 650; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pxui-slot-meta {
  display: flex; align-items: center; gap: 6px;
  font-size: 11.5px; color: var(--text-3);
}
.pxui-slot-dot { width: 7px; height: 7px; border-radius: var(--r-full); flex: none; }

.pxui-slot-tag {
  flex: none; padding: 3px 9px; border-radius: var(--r-full);
  background: var(--surface-3); color: var(--text-2);
  font-size: 11px; font-weight: 650; white-space: nowrap;
}

.pxui-slot-card-blocked {
  --pxui-event-color: var(--red);
  background-image: repeating-linear-gradient(
    -45deg,
    var(--red-tint) 0,
    var(--red-tint) 4px,
    var(--surface) 4px,
    var(--surface) 9px
  );
}
.pxui-slot-card-blocked .pxui-slot-title { color: var(--red); }

@media (max-width: 560px) {
  .pxui-slot { gap: 10px; }
  .pxui-slot-time { width: 46px; }
}

import type * as React from "react";

/**
 * Gedeeld datamodel voor alle agendaweergaven.
 *
 * WeekSchedule, ResourceColumns, Swimlanes en TimeSlotList werken op precies
 * dezelfde gegevens, zodat je met één knop van weergave kunt wisselen zonder
 * je data om te bouwen.
 */

export type ScheduleTone = "accent" | "green" | "amber" | "red" | "blue" | "violet" | "neutral";

/** Een kolom of rij in de agenda: een dag, een arts, een kamer, een machine. */
export interface ScheduleResource {
  /** Unieke sleutel; events verwijzen hiernaar. */
  key: string;
  label: React.ReactNode;
  /** Tweede regel, bv. het dagnummer of het aantal afspraken. */
  sublabel?: React.ReactNode;
  /** Avatar of icoon links van het label. */
  media?: React.ReactNode;
  /** Eigen kleur voor deze resource (koptekst, tag, blokken zonder eigen kleur). */
  color?: string;
  /** Markeert deze kolom als vandaag. */
  today?: boolean;
  /** Hele kolom gearceerd, bv. een sluitingsdag of afwezigheid. */
  blocked?: boolean;
  blockedLabel?: React.ReactNode;
}

export interface ScheduleEvent {
  id: string;
  /** Sleutel van de resource (dag, arts, kamer …) waar dit item bij hoort. */
  resource: string;
  /** Begin in minuten sinds middernacht (09:30 = 570). */
  start: number;
  /** Einde in minuten sinds middernacht. */
  end: number;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  tone?: ScheduleTone;
  /** Eigen kleur; overschrijft `tone` en de kleur van de resource. */
  color?: string;
  /** Kan niet versleept of aangepast worden. */
  locked?: boolean;
  /** Geblokkeerde tijd: gearceerd, nooit versleepbaar, geen klikactie. */
  blocked?: boolean;
  /** Vrij veld voor je eigen gegevens. */
  meta?: unknown;
}

/** Positie van een event wanneer overlappende items naast elkaar staan. */
export interface LaidOutEvent<T extends { start: number; end: number }> {
  event: T;
  /** Kolomindex binnen de groep overlappende items. */
  lane: number;
  /** Aantal kolommen in die groep. */
  lanes: number;
}

/**
 * Legt overlappende items naast elkaar: items die elkaar raken vormen een
 * cluster en krijgen daarbinnen elk een eigen kolom.
 */
export function packLanes<T extends { start: number; end: number }>(items: T[]): Array<LaidOutEvent<T>> {
  const sorted = [...items].sort((a, b) => a.start - b.start || a.end - b.end);
  const result: Array<LaidOutEvent<T>> = [];

  let cluster: T[] = [];
  let clusterEnd = -1;

  const flush = () => {
    if (cluster.length === 0) return;
    const laneEnds: number[] = [];
    const placed = cluster.map((event) => {
      let lane = laneEnds.findIndex((end) => end <= event.start);
      if (lane === -1) {
        lane = laneEnds.length;
        laneEnds.push(event.end);
      } else {
        laneEnds[lane] = event.end;
      }
      return { event, lane };
    });
    for (const entry of placed) result.push({ ...entry, lanes: laneEnds.length });
    cluster = [];
    clusterEnd = -1;
  };

  for (const event of sorted) {
    if (cluster.length > 0 && event.start >= clusterEnd) flush();
    cluster.push(event);
    clusterEnd = Math.max(clusterEnd, event.end);
  }
  flush();

  return result;
}

/** Groepeert events per resource, in de volgorde van de resources zelf. */
export function groupByResource<T extends { resource: string }>(
  events: T[],
  resources: Array<{ key: string }>
): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const resource of resources) map.set(resource.key, []);
  for (const event of events) {
    const list = map.get(event.resource);
    if (list) list.push(event);
  }
  for (const list of map.values()) {
    list.sort((a, b) => ((a as { start?: number }).start ?? 0) - ((b as { start?: number }).start ?? 0));
  }
  return map;
}

/** Groepeert events per starttijd, oplopend — de basis voor een tijdlijn. */
export function groupByStart<T extends { start: number }>(events: T[]): Array<{ start: number; events: T[] }> {
  const map = new Map<number, T[]>();
  for (const event of events) {
    const list = map.get(event.start) ?? [];
    list.push(event);
    map.set(event.start, list);
  }
  return [...map.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([start, list]) => ({ start, events: list }));
}

/** Telt de items die echt een afspraak zijn (geblokkeerde tijd niet meegerekend). */
export function countBookable(events: Array<{ blocked?: boolean }>): number {
  return events.filter((event) => !event.blocked).length;
}

/** De kleur van een event: eigen kleur, anders die van de resource, anders de toon. */
export function eventColor(
  event: { color?: string; tone?: ScheduleTone },
  resource?: { color?: string }
): string | undefined {
  return event.color ?? resource?.color;
}

/** Huidige tijd in minuten sinds middernacht. */
export function nowMinutes(): number {
  const date = new Date();
  return date.getHours() * 60 + date.getMinutes();
}
